  (243, 'REQ-0243', 'Inconsistencies - Frontend issue', '**PROBLEM STATEMENT**
This ticket is raised to address all the casing inconsistencies.

**AS A** Service
**I WANT** to correct all inconsistencies in CaTH
**SO THAT** there can be uniformity in CaTH

**ACCEPTANCE CRITERIA**
The following instances need to be corrected.

1. The opening section bullet points on the interstitial page https://cath-web.staging.platform.hmcts.net/ need to be updated to read as follows;

Court and tribunal hearings
You can use this service to get information about:

Hearings in Civil and Family Courts in England and Wales
Hearings in First Tier and Upper Tribunals (excluding Employment Tribunals)
Hearings in the Royal Courts of Justice and the Rolls Building
Hearings in Crown Courts in England and Wales
Hearings in Magistrates'' Courts in England and Wales
Single Justice Procedure cases, including TV licensing and minor traffic offences such as speeding

2. On the ''Find a court or tribunal'' https://cath-web.staging.platform.hmcts.net/courts-tribunals-list page

- Additional ''Region'' options to be created in Page are East of England, National, Northern Ireland, Royal Courts of Justice Group.
- ''High Court'' to be added as additional option and the ''Court of Appeal'' option is updated to Court of Appeal (Civil Division) on the ''Type of civil court'' filter
- ''High Court of the Family Division'' to be added as additional option on the ''Type of family court'' filter
- Additional options to be added on the ''Type of tribunal'' filter include Asylum Support Tribunal, Criminal Injuries Compensation Tribunal, First-Tier Tribunal (Lands Registration Tribunal), First-tier Tribunal (Special Educational Needs and Disability), First-Tier Tribunal (Tax Chamber), First-Tier Tribunal (War Pensions and Armed Forces Compensation), General Regulatory Chamber, Mental Health Tribunal, Pathogens Access Appeal Commission, 
Primary Health Tribunal, Proscribed Organisations Appeal Commission, Residential Property Tribunal, Residential Property Tribunal, Special Immigration Appeals Commission, Upper Tribunal (Administrative Appeals Chamber), Upper Tribunal (Immigration and Asylum) - Judicial Review, Upper Tribunal (Immigration and Asylum) - Statutory Appeal, Upper Tribunal (Lands Chamber) and Upper Tribunal (Tax and Chancery Chamber)

3. Missing venues need to be added. 

- Only the following venues are available on the ''Find a court or tribunal page'' ; Birmingham Civil and Family Justice Centre, Birmingham Crown Court, Birmingham Magistrates'' Court, Bristol Civil and Family Justice Centre, Cardiff Civil and Family Justice Centre, Leeds Combined Court Centre, Liverpool Civil and Family Court, Liverpool Social Security and Child Support Tribunal, London Social Security and Child Support Tribunal, Manchester Civil Justice Centre, Midlands Social Security and Child Support Tribunal, Newcastle Combined Court Centre, North East Social Security and Child Support Tribunal, North West Social Security and Child Support Tribunal, Oxford Combined Court Centre, Royal Courts of Justice, Scotland Social Security and Child Support Tribunal, Single Justice Procedure, South East Social Security and Child Support Tribunal, Wales and South West Social Security and Child Support Tribunal

4. On the Manual upload journey, the page title on the ''File Upload Summary'' page, only 1st word capitalized (File upload summary). This should be changed to each word Capitalized (File Upload Summary).',
