VALUES
  (285, 'REQ-0285', 'Bug: Magistrate Standard List not showing Prosecuting authority properly in Email Summary', 'Magistrate Standard List not showing Prosecuting authority properly in Email Summary. If Prosecuting authority is empty, we still not show Prosecuting authority as empty value.

For example, in CaTH ORG:
Name – Gerhold, Danielle
Prosecuting authority -
Reference – SJ236059885
Hearing type – Application
Offence – Appearance to make statutory declaration (SJP case)

In CaTH AI:
Name – Gerhold, Danielle
Reference – SJ236059885
Hearing type – Application
Offence – Appearance to make statutory declaration (SJP case)

It should match CaTH ORG.',
   'functional', 'approved', NULL, NULL,
